"""Offline operator page; human annotations remain separate from engine evidence."""
from __future__ import annotations

import html
import json


STYLE = r'''
:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;line-height:1.55;color:#253c32;background:#f2f2e9;font-synthesis:none}
*{box-sizing:border-box}body{margin:0}button,input,select,textarea{font:inherit}button,a,input,select,textarea{-webkit-tap-highlight-color:transparent}a{color:#306346;text-underline-offset:3px}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}[hidden]{display:none!important}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid #bc742b;outline-offset:3px}
.shell{max-width:1320px;margin:0 auto;padding:32px 36px 46px}.masthead{display:flex;justify-content:space-between;align-items:center;gap:20px;padding-bottom:22px;border-bottom:1px solid #c5d0bf}.brand{font-weight:800;font-size:23px;letter-spacing:-.065em}.brand span{color:#708341}.mode{font-size:11px;letter-spacing:.13em;font-weight:700;color:#617158}.intro{padding:35px 0 28px;display:flex;align-items:end;justify-content:space-between;gap:32px}.eyebrow{font-size:10px;font-weight:800;letter-spacing:.16em;color:#6b7d44;text-transform:uppercase;margin:0 0 7px}h1{font-size:clamp(32px,4.6vw,58px);line-height:1.1;letter-spacing:-.06em;margin:0 0 14px}h2{font-size:22px;letter-spacing:-.03em;line-height:1.2;margin:0}h3{font-size:17px;margin:0}.intro p:not(.eyebrow){font-size:14px;max-width:660px;margin:0;color:#596c5e}.count-stamp{text-align:right;flex-shrink:0}.count-stamp strong{font-size:42px;font-weight:750;line-height:1;letter-spacing:-.06em;display:block;color:#365538}.count-stamp span{font-size:11px;color:#6c785f}.capture-state{border-left:4px solid #a17138;background:#e9e8d6;padding:18px 22px;margin-bottom:24px;border-radius:0 7px 7px 0}.capture-state .state-code{font-weight:800;font-size:15px;color:#59462c;overflow-wrap:anywhere}.capture-state p{margin:7px 0 0;font-size:12px;color:#6b5d48}.reason-list{padding:0;list-style:none;display:flex;flex-wrap:wrap;gap:7px;margin:11px 0 0}.reason-list li{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:10px;line-height:1.5;padding:4px 7px;border:1px solid #cfc4a9;border-radius:4px;overflow-wrap:anywhere}
.workspace{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:24px;align-items:start}.capture-panel,.review-panel,.evidence{background:#fffef8;border:1px solid #cdd3c2;border-radius:10px;overflow:hidden}.panel-heading{padding:23px 24px 18px;border-bottom:1px solid #e1e4d6}.panel-heading p{margin:7px 0 0;font-size:12px;color:#687561}.image-frame{margin:0;padding:17px;background:#e7ebdf}.image-frame img{display:block;width:100%;height:auto;border-radius:5px;background:#d3dbcc}.image-frame figcaption{font-size:11px;color:#52644f;line-height:1.6;margin-top:12px}.capture-facts{padding:16px 24px;display:grid;grid-template-columns:1fr 1fr;gap:15px;margin:0}.capture-facts dt{font-size:10px;color:#6d7d65;text-transform:uppercase;letter-spacing:.1em}.capture-facts dd{margin:3px 0 0;font-size:12px;font-weight:650;color:#344d39;overflow-wrap:anywhere}.capture-links{padding:0 24px 20px;display:flex;flex-wrap:wrap;gap:15px;font-size:12px}.limits{border-top:1px solid #e0e4d5;padding:17px 24px}.limits summary{cursor:pointer;font-size:12px;font-weight:700}.limits ul{padding-left:18px;color:#65725e;font-size:11px;line-height:1.8;margin-bottom:0}
.review-toolbar{padding:19px 22px;background:#f7f8ef;border-bottom:1px solid #dde2d1;display:grid;grid-template-columns:1fr 1fr;gap:14px}.review-toolbar label,.candidate-fields label{font-size:11px;font-weight:650;display:flex;flex-direction:column;gap:6px;color:#52664c}.review-toolbar input,.review-toolbar select,.candidate-fields select,.candidate-fields textarea{min-width:0;width:100%;border:1px solid #bfcbb5;background:#fffef9;border-radius:5px;color:#294231;padding:9px 10px;font-size:12px;line-height:1.5}.review-toolbar small{font-size:10px;color:#7b836d;font-weight:400}.review-summary{padding:12px 22px;border-bottom:1px solid #e3e7d8;font-size:11px;font-weight:650;color:#60734e;margin:0}.candidate-list{padding:0 22px;max-height:720px;overflow:auto;scrollbar-color:#b7c7a4 #f2f4e8}.candidate-list>p{font-size:13px;color:#6b7c60;padding:10px 0}.candidate-card{padding:20px 0;border-bottom:1px solid #e1e6d6}.candidate-card:last-child{border-bottom:0}.candidate-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;font-size:15px;font-weight:750;color:#345333;line-height:1.5}.candidate-heading h3{font-size:15px}.candidate-heading small,.candidate-heading span{font-size:11px;color:#6c815d;font-weight:500}.candidate-geometry{font-size:11px;color:#76866a;line-height:1.7;margin:7px 0 13px;overflow-wrap:anywhere}.candidate-fields{display:grid;grid-template-columns:minmax(125px,.75fr) minmax(0,1.25fr);gap:12px;align-items:start}.candidate-fields textarea{min-height:72px;resize:vertical}.candidate-crop{display:block;width:100%;max-height:200px;aspect-ratio:1.5;object-fit:contain;background:#e6ecdf;border:1px solid #d2dcc8;border-radius:6px;margin:12px 0 15px}.review-pagination{display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid #e1e6d6;padding:14px 22px}.review-pagination span{font-size:11px;color:#687f58;text-align:center}.review-pagination button{font-size:11px;padding:8px 11px}.review-actions{padding:18px 22px;display:flex;flex-wrap:wrap;gap:10px;border-top:1px solid #dde3d1;background:#f8f9f0}button,.import-control{border:1px solid #aec19e;border-radius:5px;padding:10px 14px;color:#3c593b;font-size:12px;background:#f6f9ee;font-weight:650}.primary{background:#345d37;color:#fffde9;border-color:#345d37}button:hover{filter:brightness(.96)}.import-control{display:flex;flex-direction:column;gap:7px;max-width:100%;flex:1 1 180px}.import-control input{font-size:11px;font-weight:400;min-width:0;width:100%;color:#607158}.review-feedback{padding:0 22px 18px;background:#f8f9f0}.review-feedback p{font-size:11px;margin:0;line-height:1.7;overflow-wrap:anywhere}.review-feedback .error{color:#923d2c;background:#f8e7dc;border-left:3px solid #b3563b;padding:10px 12px;margin-top:10px}.save-note{font-size:10px;color:#748266;margin-top:10px!important}
.evidence{margin-top:24px;padding:23px 25px}.evidence h2{font-size:18px}.source-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:18px 0 0}.source-grid dt{font-size:10px;text-transform:uppercase;letter-spacing:.1em;color:#728168;margin:0 0 6px}.source-grid dd{margin:0}.source-grid code{font-size:11px;overflow-wrap:anywhere;color:#486243}.evidence p{font-size:11px;color:#6d7f62;margin:16px 0 0}footer{font-size:11px;color:#7a866b;margin-top:23px;line-height:1.8}noscript p{padding:14px;border:1px solid #bc9060;background:#f2e5cf;font-size:13px}
@media(min-width:1100px){.capture-panel{position:sticky;top:22px}}@media(max-width:900px){.workspace{grid-template-columns:1fr}.candidate-list{max-height:none}.shell{padding:25px}.intro{padding:28px 0}.count-stamp strong{font-size:34px}.source-grid{grid-template-columns:1fr}}
@media(max-width:520px){.shell{padding:17px}.masthead{align-items:start}.mode{max-width:100px;text-align:right;font-size:9px}.intro{gap:18px;align-items:start}.count-stamp{padding-top:24px}.count-stamp span{display:block;max-width:80px}.intro p:not(.eyebrow){font-size:12px}.panel-heading{padding:20px}.review-toolbar{grid-template-columns:1fr}.candidate-fields{grid-template-columns:1fr}.capture-facts{grid-template-columns:1fr 1fr;padding:17px 20px}.capture-state{padding:16px}.capture-state .state-code{font-size:12px}.review-actions>button{width:100%}.evidence{padding:20px}}
@media print{body{background:#fff}.shell{padding:0}.workspace{display:block}.capture-panel{position:static}.review-panel{margin-top:20px}.candidate-list{max-height:none;overflow:visible}.review-toolbar,.review-actions,.review-pagination,.save-note{display:none}.image-frame img{max-height:450px;object-fit:contain}.candidate-card,.capture-state,.evidence{break-inside:avoid}}
'''


def render_page(report: dict, report_sha256: str) -> str:
    """Present unchanged engine facts with a separate source-bound labeling desk."""
    escape = lambda value: html.escape(str(value), quote=True)
    decision = report['decision']
    reasons = ''.join(f'<li>{escape(value)}</li>' for value in decision['reason_codes'])
    if not reasons:
        reasons = '<li>No immediate capture issue reported</li>'
    limitations = ''.join(f'<li>{escape(value)}</li>' for value in report['limitations'])
    width, height = report['image_dimensions_px']
    marker = report.get('reference_marker')
    scale = (f"Approximate, marker {escape(marker['id'])}" if marker else 'Unavailable in this capture')
    payload = json.dumps({'report_sha256': report_sha256, 'report': report},
                         ensure_ascii=True, allow_nan=False).replace('<', '\\u003c')
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>OrchardCue · Candidate review</title><style>{STYLE}</style></head>
<body><main class="shell">
<header class="masthead"><div class="brand">Orchard<span>Cue</span></div><div class="mode">CAPTURE / OPERATOR REVIEW</div></header>
<section class="intro"><div><p class="eyebrow">From image to observation</p><h1>Review the capture.</h1><p>Inspect each numbered region and record what you can see. Your labels stay separate from the original image analysis.</p></div><div class="count-stamp"><strong>{escape(report['candidate_count'])}</strong><span>red fruit-like candidates</span></div></section>
<section class="capture-state" aria-label="Original capture decision"><div class="state-code">{escape(decision['action'])}</div><ul class="reason-list">{reasons}</ul><p>The original capture decision remains in force when labels are added. An observation does not establish crop yield, ripeness or treatment.</p></section>
<noscript><p>JavaScript is needed to record and export candidate labels. The original capture, reasons and evidence remain readable below.</p></noscript>
<div class="workspace">
<section class="capture-panel" aria-labelledby="captureHeading"><div class="panel-heading"><p class="eyebrow">01 / Captured evidence</p><h2 id="captureHeading">See the whole frame</h2><p>Candidate numbers match the labels in the annotated image.</p></div>
<figure class="image-frame"><img src="overlay.png" width="{escape(width)}" height="{escape(height)}" alt="Annotated capture showing numbered red fruit-like candidates and the original review status"><figcaption>{escape(report['ambiguous_regions'])} ambiguous red regions were reported separately. Those regions are not added to the numbered candidate list.</figcaption></figure>
<dl class="capture-facts"><div><dt>Image dimensions</dt><dd>{escape(width)} × {escape(height)} px</dd></div><div><dt>Physical scale</dt><dd>{scale}</dd></div><div><dt>Analysis engine</dt><dd>{escape(report['engine'])}</dd></div><div><dt>Confirmation</dt><dd>Operator review required</dd></div></dl>
<div class="capture-links"><a href="overlay.png" download>Download annotated image</a><a href="report.json" download>Original analysis JSON</a></div>
<details class="limits"><summary>Capture and measurement limitations</summary><ul>{limitations}</ul></details></section>
<section class="review-panel" aria-labelledby="reviewHeading"><div class="panel-heading"><p class="eyebrow">02 / Your observations</p><h2 id="reviewHeading">Label the visible candidates</h2><p>Leave anything unresolved as unreviewed or uncertain. Labels describe appearance in this image.</p></div>
<div class="review-toolbar"><label for="reviewFilter">Show candidates<select id="reviewFilter"><option value="all">All candidates</option><option value="unreviewed">Unreviewed</option><option value="reviewed">Reviewed</option><option value="uncertain">Uncertain</option></select></label><label for="reviewReviewer">Reviewer name · optional<input id="reviewReviewer" type="text" maxlength="120" autocomplete="off" placeholder="Name or initials"><small>Attribution saved with your labels.</small></label></div>
<p id="reviewSummary" class="review-summary" role="status" aria-live="polite">Preparing candidate review…</p>
<div id="candidateList" class="candidate-list"><p>Loading the numbered candidates…</p></div>
<nav class="review-pagination" aria-label="Candidate pages"><button id="reviewPrevious" type="button" disabled>← Previous</button><span id="reviewPage" role="status" aria-live="polite">Page 1</span><button id="reviewNext" type="button" disabled>Next →</button></nav>
<div class="review-actions"><button id="reviewExport" class="primary" type="button">Download review JSON</button><label class="import-control" for="reviewImport">Resume a saved review<input id="reviewImport" type="file" accept=".json,application/json" aria-describedby="reviewStatus"></label></div>
<div class="review-feedback"><p id="reviewStatus" role="status" aria-live="polite">Review labels are kept separately from the original analysis.</p><p id="reviewError" class="error" role="alert" hidden></p><p class="save-note">Download your review to keep it. When browser storage is available, it can also retain a draft for this exact report.</p></div></section></div>
<section class="evidence" aria-labelledby="sourceHeading"><h2 id="sourceHeading">Tied to this capture</h2><dl class="source-grid"><div><dt>Input image · SHA-256</dt><dd><code>{escape(report['input_sha256'])}</code></dd></div><div><dt>Original report · SHA-256</dt><dd><code>{escape(report_sha256)}</code></dd></div></dl><p>A saved review belongs to these source files. Importing it restores labels and notes without rewriting the engine's observations.</p></section>
<footer>OrchardCue · Offline image review. All observations require interpretation in the context of the capture and its stated limitations.</footer>
</main><script id="reviewSource" type="application/json">{payload}</script><script src="./review.js" defer></script></body></html>'''
